script:
foreach (var p; ["/controls/flight/aileron", "/controls/flight/elevator", "/controls/flight/rudder", "/controls/flight/aileron[1]", "/controls/flight/elevator[1]", "/controls/flight/rudder[1]"]) { setprop(p, 0); }
fmgc.Input.fd1.setBoolValue(1);
fmgc.Input.lat.setValue(3);
fmgc.Input.alt.setValue(35000);
fmgc.Input.vert.setValue(4);
fmgc.Input.ktsMach.setBoolValue(0);
fcu.FCUController.SPDPull();
fmgc.Input.kts.setValue(220);
var cl = (getprop("/systems/acconfig/options/fadec/climb-b") + getprop("/systems/acconfig/options/fadec/climb-t")) / 2;
setprop("/controls/engines/engine[0]/throttle", cl);
setprop("/controls/engines/engine[1]/throttle", cl);
if (!fmgc.Output.ap1.getBoolValue()) { fcu.FCUController.AP1(); }
